INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('159756f7-f9c7-4266-ba51-d3b7997df699', '14471ded-ebd1-4ac3-a1a7-fca0c1998bc8', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Centro Las Américas Lease: Centro Regional Las Américas, S. de R.L. de C.V. (05/27/2024 - 12/06/2034)', NULL, false, 'activo', 'Lease', NULL, '2024-12-07', '2024-08-02', '2034-12-06', NULL, false, NULL, NULL, 0, NULL, NULL, NULL, NULL, 126, 'Centro Regional Las Américas, S. de R.L. de C.V.', NULL, NULL, 'Insurgentes Sur 286', '5° Piso', 'Roma, Cuauhtémoc', 'Ciudad de México', '06700', NULL, 'Enrique Cortés Soriano | Miguel Ángel Cinco González', NULL, NULL, 150, 'percent', NULL, 278295.34, 2996313.13, 'El Arrendatario deberá cubrir en la Fecha de Entrega del Bien Arrendado la cantidad de $2,996,313.13 M.N., más, lo que es equivalente a 10 meses y 23 días de Renta. Las Rentas Anticipadas contempladas en la presente Cláusula corresponden a los primeros 10 meses y 23 días de Renta de conformidad con la Fecha de Inicio de la Obligación del Pago de la Renta.', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('159756f7-f9c7-4266-ba51-d3b7997df699', 'Domicilio del Contrato', E'Avenida Central esquina Primero de Mayo, Manzana 4, Lote 1 Colonia Las Américas, Municipio de Ecatepec de Morelos, Código Postal 55076, Estado de México\nLocal número L-12-13', 'America Gonzalez', NULL);
