INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('159756f7-f9c7-4266-ba51-d3b7997df699', 'Fecha de Firma del Contrato', '27 de mayo de 2024', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('159756f7-f9c7-4266-ba51-d3b7997df699', 'Incremento de Renta', '16', '6', 'INCREMENTO EN LA RENTA FIJA', E'- The fixed rent will increase annually starting from the rent payment start date, every January 1st.\n- The increase will match the percentage rise in the National Consumer Price Index (INPC) published by INEGI.\n- The first increase will occur after 24 months from the rent payment start date, unless stated otherwise in the following paragraph.\n- If the INPC is not published by January 1st, a provisional estimate will be used until the official index is available.\n- Once the official index is published, the rent will be adjusted retroactively to reflect the correct increase.', E'Las Partes convienen en que la Renta Fija se incrementará de manera anual a partir de la Fecha de Inicio de la Obligación del pago de la Renta, el primero de enero de cada año, en un porcentaje igual al incremento que muestre el Índice Nacional de Precios al Consumidor ("INPC") publicado por el Instituto Nacional de Estadística y Geografía (INEGI) en el Diario Oficial de la Federación, siendo que las Partes acuerdan que el primer incremento será precisamente al cumplir los primeros 24 (veinticuatro) meses contados a partir de la Fecha de Inicio de la Obligación del pago de la Renta, salvo que se presente el supuesto establecido en el párrafo inmediato siguiente.\n\nEn el caso de que para el primero de enero de cada año, según sea el caso, no se hubiere publicado el referido INPC, la actualización se hará provisionalmente con el índice estimado, hasta que se realice la publicación respectiva, momento en el que se determinará el ajuste definitivo, mismo que se aplicará retroactivamente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('159756f7-f9c7-4266-ba51-d3b7997df699', 'Late Fees', '36', '29', 'INTERESES MORATORIOS', E'- If a party fails to meet any financial obligation on time, they must pay the other party interest for each day of delay.\n- The interest is calculated daily using the 91-day Interbank Equilibrium Interest Rate (TIIE) published by the Bank of Mexico.\n- This rate is multiplied by 4.\n- If the rate is not published on the day the default begins, the most recently published rate will be used.', 'La Parte que no cumpla oportunamente con cualquier obligación de carácter económico estipulada en este Contrato, deberá cubrir a la Parte que tenga derecho a recibir la prestación económica, un interés moratorio calculado diariamente por cada día de retraso, equivalente a aplicar al monto de la obligación incumplida, la Tasa de Interés Interbancaria de Equilibrio (TIIE) a plazo de 91 (noventa y un) días, que publique el Banco de México en el Diario Oficial de la Federación, el día que inicie el incumplimiento, multiplicada por 4 (cuatro). Si el día en que inicie el incumplimiento no se publicara dicha tasa, se tomará la última tasa que se hubiere publicado previa a dicho día.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('159756f7-f9c7-4266-ba51-d3b7997df699', 'Common Area Maintenance Charges', '10', '3 B.', 'RENTA ADICIONAL', E'- Monthly amount is 15% of the Fixed Rent.\n- Plus applicable VAT (Value Added Tax).\n- This is referred to as "Additional Rent."', 'La cantidad mensual equivalente al 15% (quince por ciento) de la Renta Fija, más el IVA correspondiente (la "Renta Adicional").');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('159756f7-f9c7-4266-ba51-d3b7997df699', 'Percentage Rent', '25', '14', 'OBLIGACIONES ESPECÍFICAS Y RENUNCIAS DEL ARRENDATARIO', E'- No hay renta porcentual, pero el arrendatario debe enviar un reporte mensual de ventas netas al arrendador dentro de 15 días naturales.\n- El reporte debe ser enviado a la dirección de correo proporcionada y firmado por un representante del arrendatario.\n- Si el arrendatario no cumple con esta obligación dos veces en seis meses, el contrato puede ser rescindido y se aplicará una penalización.\n- La penalización será la mayor entre la establecida en el contrato o el equivalente a la renta fija multiplicada por los meses restantes del contrato.\n- El arrendatario debe mantener registros de ventas y contabilidad por 36 meses, ya sea en el local arrendado o en su domicilio.\n- El arrendador puede inspeccionar estos documentos con 72 horas de aviso.\n- Los registros deben seguir los principios de contabilidad generalmente aceptados en México y la legislación aplicable.', E'No hay renta porcentual, sin embargo, es obligación del Arrendatario:\nEntregar al Arrendador dentro de los 15 (quince) Días Naturales, a la cuenta de correo electrónico overage@centrolasamericas.com o cualquier otra cuenta que de tiempo en tiempo le notifique por escrito el Arrendador, un reporte mensual de las Ventas Netas que haya realizado el Arrendatario en el Bien Arrendado durante el mes inmediato anterior, el cual deberá ser firmado por un representante del Arrendatario. El incumplimiento a esta obligación, durante 2 (dos) ocasiones en un periodo de 6 (seis) meses, será causa de rescisión del presente Contrato y el Arrendatario se hará acreedor a la pena convencional que resulte mayor entre (i) la pena convencional establecida en la Cláusula Vigésima Octava de este Contrato; o (ii) a la cantidad equivalente a la Renta Fija multiplicada por los meses restantes por devengar hasta cumplir con la Fecha de Término del Contrato. Asimismo el Arrendatario se obliga a mantener ya sea, en el Bien Arrendado o en el domicilio del Arrendatario especificado en este Contrato y hasta por un periodo de 36 (treinta y seis) meses de antigüedad todos reportes de Ventas Netas, así como, los registros y libros contables (incluyendo en forma enunciativa más no limitativa, recibos de venta, registros de cajas registradoras, registros de tarjetas de crédito, órdenes telefónicas, por correo o por internet, registros de cómputo, listas de compra e inventarios, declaraciones de impuestos, etc.) que sean necesarios para permitir que el Arrendador, o a cualquier persona designada por el Arrendador, compruebe las Ventas Netas correspondientes a cualquier mes, en el entendido que el Arrendador tendrá el derecho de hacer inspecciones a dichos documentos, previa notificación que realice al Arrendatario con al menos 72 (setenta y dos) horas a la fecha en que pretenda realizar la inspección. Dichos registros y libros contables deberán mantenerse de conformidad con los principios de contabilidad generalmente aceptados en México, así como, con la legislación aplicable en México, y asegurar el correcto registro de todas las Ventas Netas, sus exclusiones y deducciones.');
