INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('e7d6d524-f748-4e25-ab8e-a508cb5ae805', 'Late Fees', '3', '3', 'RENTA', E'- If the Tenant is late or fails to pay the Rent, they must pay the Landlord a penalty.\n- The penalty is 2% per month of the overdue or unpaid Rent.\n- This penalty starts from the second consecutive month of late or missed Rent payment.', 'En caso de retraso o incumplimiento en el pago de la Renta, el Arrendatario se obliga a pagar al Arrendador por concepto de retraso en el pago el dos por ciento (2%) mensual de cada Renta incumplida o retrasada. Dicha penalidad comenzará a partir del segundo mes consecutivo de retraso o incumplimiento de pago de Renta.');
